[CmdletBinding(DefaultParameterSetName='Entries')]
param([Parameter(Mandatory=$true)][string]$TaskDirectory,[Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(ParameterSetName='Entries',Mandatory=$true)][string[]]$Paths,[Parameter(ParameterSetName='Entries')][ValidateSet('add','modify','delete','restore')][string]$Operation='modify',[Parameter(ParameterSetName='Entries')][string[]]$RequirementIds,[Parameter(ParameterSetName='Entries')][string[]]$WorkItemIds,[Parameter(ParameterSetName='Entries')][string]$RequirementsHash,[Parameter(ParameterSetName='Entries')][string]$ComplexityHash,[Parameter(ParameterSetName='ScopeJson',Mandatory=$true)][string]$ScopeJson)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'PipelineGitScope.psm1') -Force;$input=if($PSCmdlet.ParameterSetName -eq 'ScopeJson'){Get-Content -Raw $ScopeJson|ConvertFrom-Json}else{[pscustomobject]@{paths=[ordered]@{}}};$entries=[ordered]@{};if($PSCmdlet.ParameterSetName -eq 'ScopeJson'){$entries=$input.paths;$RequirementsHash=$input.requirements_hash;$ComplexityHash=$input.complexity_hash}else{foreach($p in $Paths){if($entries.Contains($p.Replace('\','/'))){throw "duplicate scope path: $p"};$entries[$p.Replace('\','/')]=[pscustomobject]@{path=$p.Replace('\','/');kind='file';operations=@($Operation);requirement_ids=@($RequirementIds);work_item_ids=@($WorkItemIds)}}};if([string]::IsNullOrWhiteSpace($RequirementsHash) -or [string]::IsNullOrWhiteSpace($ComplexityHash)){throw 'scope requires requirements_hash and complexity_hash'};foreach($p in @($entries.Keys)){Test-PipelineScopePaths @($p) $ProjectRoot|Out-Null;$e=$entries[$p];if($e.kind -ne 'file' -or @($e.operations).Count -eq 0 -or @($e.requirement_ids).Count -eq 0 -or @($e.work_item_ids).Count -eq 0){throw "invalid exact scope entry: $p"}};$dir=Join-Path $TaskDirectory 'scope-revisions';[IO.Directory]::CreateDirectory($dir)|Out-Null;$n=1;while($true){$id='SCOPE-{0:D4}' -f $n;$file=Join-Path $dir "$id.json";try{$scope=[ordered]@{protocol_version=2;revision_id=$id;paths=$entries;requirements_hash=$RequirementsHash;complexity_hash=$ComplexityHash;created_at=[datetime]::UtcNow.ToString('o')};Write-PipelineImmutableJson $file $scope|Out-Null;break}catch{$n++}};$hash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();Write-AtomicJson (Join-Path $TaskDirectory 'scope-current.json') ([ordered]@{protocol_version=2;type='scope';revision_id=$id;path=(Join-Path 'scope-revisions' "$id.json");sha256=$hash});$scope|ConvertTo-Json -Depth 20
